//! LR driver over the comb-packed tables generated by `build/codegen.rs`.
//!
//! No per-call setup: the tables are decoded once (`OnceLock`) from `include_bytes!`, and the
//! three parse stacks (states, values, spans) are reused across calls.
use std::sync::OnceLock;

use crate::{
    actions::{EOF, PROD_LEN, PROD_LHS, REDUCERS, StartT, V, take_start},
    actions_rt::SrcText,
    ctx::Ctx,
    lexer::Tok,
    span::Span,
};

/// Source text handle passed to actions as `$lexer`.
pub struct Src<'a> {
    pub src: &'a str,
}

impl SrcText for Src<'_> {
    #[inline]
    fn src_str(&self, span: Span) -> &str {
        &self.src[span.start()..span.end()]
    }
}

/// Action value encoding (see `build/codegen.rs`).
const ACCEPT: i32 = i32::MIN;

struct Tables {
    start: u32,
    default: Vec<i32>,
    abase: Vec<i32>,
    acheck: Vec<u32>,
    aval: Vec<i32>,
    gbase: Vec<i32>,
    gcheck: Vec<u32>,
    gval: Vec<u32>,
}

static RAW: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/tables.bin"));

fn tables() -> &'static Tables {
    static T: OnceLock<Tables> = OnceLock::new();
    T.get_or_init(|| {
        let mut it = RAW
            .chunks_exact(4)
            .map(|c| u32::from_le_bytes([c[0], c[1], c[2], c[3]]));
        let mut take = |n: usize| -> Vec<u32> { (&mut it).take(n).collect() };
        let h = take(4);
        let (ns, al, gl) = (h[0] as usize, h[1] as usize, h[2] as usize);
        let i = |v: Vec<u32>| v.into_iter().map(|x| x as i32).collect::<Vec<i32>>();
        let t = Tables {
            start: h[3],
            default: i(take(ns)),
            abase: i(take(ns)),
            acheck: take(al),
            aval: i(take(al)),
            gbase: i(take(ns)),
            gcheck: take(gl),
            gval: take(gl),
        };
        assert_eq!(t.gval.len(), gl, "truncated parser tables");
        t
    })
}

impl Tables {
    #[inline(always)]
    fn action(&self, s: u32, t: u32) -> i32 {
        let i = self.abase[s as usize] as isize + t as isize;
        if i >= 0 && (i as usize) < self.acheck.len() && self.acheck[i as usize] == s {
            self.aval[i as usize]
        } else {
            self.default[s as usize]
        }
    }

    #[inline(always)]
    fn goto(&self, s: u32, r: u32) -> u32 {
        let i = (self.gbase[s as usize] as isize + r as isize) as usize;
        debug_assert_eq!(self.gcheck[i], s);
        self.gval[i]
    }
}

pub enum Outcome {
    Ok(StartT),
    /// No action for the token at this index of the token slice (`== len` for end of input).
    Syntax {
        tok_index: usize,
    },
    /// An action called `ctx.fail()` (goyacc `return 1`): parsing stopped right after that
    /// reduction. The error is in `ctx.errors`.
    Aborted,
}

/// Reusable driver state: keeps its stacks between calls.
#[derive(Default)]
pub struct Driver {
    states: Vec<u32>,
    vals: Vec<V>,
    spans: Vec<(u32, u32)>,
}

impl Driver {
    pub fn parse(&mut self, src: &str, toks: &[Tok], ctx: &Ctx) -> Outcome {
        let t = tables();
        let lx = Src { src };
        self.states.clear();
        self.vals.clear();
        self.spans.clear();
        self.states.push(t.start);
        let mut i = 0usize;
        let eof_pos = src.len() as u32;
        loop {
            let (tid, ts, te) = match toks.get(i) {
                Some(tk) => (tk.id, tk.start as u32, tk.end as u32),
                None => (EOF, eof_pos, eof_pos),
            };
            let s = *self.states.last().unwrap();
            let a = t.action(s, tid);
            if a > 0 {
                // shift
                self.states.push((a - 1) as u32);
                self.vals.push(V::Tok(Tok {
                    id: tid,
                    start: ts as usize,
                    end: te as usize,
                }));
                self.spans.push((ts, te));
                i += 1;
            } else if a < 0 && a != ACCEPT {
                // reduce
                let p = (-a - 1) as usize;
                let n = PROD_LEN[p] as usize;
                let len = self.spans.len();
                // An empty production gets the span of the previous stack symbol (or 0..0),
                // as in grmtools' lrpar. See README "Open design points".
                let span = if n == 0 {
                    match self.spans.last() {
                        Some(&(a, b)) => Span::new(a as usize, b as usize),
                        None => Span::new(0, 0),
                    }
                } else {
                    Span::new(
                        self.spans[len - n].0 as usize,
                        self.spans[len - 1].1 as usize,
                    )
                };
                REDUCERS[p](&mut self.vals, &lx, span, ctx);
                self.spans.truncate(len - n);
                self.spans.push((span.start() as u32, span.end() as u32));
                self.states.truncate(self.states.len() - n);
                let top = *self.states.last().unwrap();
                self.states.push(t.goto(top, u32::from(PROD_LHS[p])));
                if ctx.abort.get() {
                    return Outcome::Aborted;
                }
            } else if a == ACCEPT {
                return Outcome::Ok(take_start(self.vals.pop().unwrap()));
            } else {
                return Outcome::Syntax { tok_index: i };
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tables_are_consistent() {
        let t = tables();
        let n = t.default.len();
        assert!(n > 5000, "expected the full TiDB automaton, got {n} states");
        assert_eq!(t.abase.len(), n);
        assert_eq!(t.gbase.len(), n);
        assert!((t.start as usize) < n);
        // Every packed entry belongs to a real state and points to a real state / production.
        for (&c, &v) in t.acheck.iter().zip(&t.aval) {
            if c == u32::MAX {
                continue;
            }
            assert!((c as usize) < n);
            if v > 0 {
                assert!(((v - 1) as usize) < n);
            } else if v != ACCEPT {
                assert!(v < 0 && ((-v - 1) as usize) < PROD_LEN.len());
            }
        }
        for (&c, &v) in t.gcheck.iter().zip(&t.gval) {
            if c != u32::MAX {
                assert!((c as usize) < n && (v as usize) < n);
            }
        }
        // Defaults are reductions or errors, never shifts.
        assert!(t.default.iter().all(|&d| d <= 0));
    }

    #[test]
    fn empty_row_never_matches() {
        // A lookup for an out-of-range column must fall back to the default, not panic.
        let t = tables();
        for s in [0u32, t.start, (t.default.len() - 1) as u32] {
            let _ = t.action(s, u32::MAX >> 8);
        }
    }
}
